WITH fixes(slug,pos,why) AS (VALUES ('administrativo-responsabilidade-civil-do-estado',5,'Correto. O art. 37, § 6º, da Constituição estabelece responsabilidade das pessoas jurídicas de direito público pelos danos que seus agentes, nessa qualidade, causem a terceiros.'),
('administrativo-responsabilidade-civil-do-estado',6,'Correto. O art. 37, § 6º, da Constituição também alcança pessoas jurídicas de direito privado prestadoras de serviços públicos, quanto aos danos causados por seus agentes nessa qualidade.'),
('administrativo-responsabilidade-civil-do-estado',7,'Correto. O art. 37, § 6º, da Constituição assegura ação regressiva contra o agente responsável quando demonstrados dolo ou culpa.'),
('administrativo-responsabilidade-civil-do-estado',9,'Correto. O art. 37, § 6º, da Constituição exige vínculo entre o dano e a atuação do agente público nessa qualidade; não basta uma conduta estritamente particular.'),
('administrativo-responsabilidade-civil-do-estado',11,'Correto. O art. 5º, LXXV, da Constituição assegura indenização pelo Estado ao condenado por erro judiciário.'),
('administrativo-responsabilidade-civil-do-estado',12,'Correto. O art. 5º, LXXV, da Constituição também garante indenização a quem ficar preso além do tempo fixado na sentença.'),
('administrativo-responsabilidade-civil-do-estado',14,'Correto. O art. 37, § 6º, da Constituição refere-se aos danos causados a terceiros pelos agentes das pessoas jurídicas abrangidas, nessa qualidade.'),
('administrativo-responsabilidade-civil-do-estado',17,'Correto. A ação de regresso prevista no art. 37, § 6º, da Constituição dirige-se ao agente causador do dano quando houver dolo ou culpa.'),
('administrativo-responsabilidade-civil-do-estado',19,'Correto. A responsabilidade da pessoa jurídica perante o terceiro não afasta o direito de regresso contra o agente, nos casos de dolo ou culpa, conforme art. 37, § 6º.'),
('servidores-lei-8112-pad-sindicancia-ritos-prescricao',2,'Correto. O art. 138 da Lei 8.112/1990 caracteriza abandono de cargo pela ausência intencional ao serviço por mais de trinta dias consecutivos.'),
('servidores-lei-8112-posse-exercicio-vacancia-remocao',5,'Correto. O art. 7º da Lei 8.112/1990 determina que a investidura em cargo público ocorre com a posse; exercício é etapa distinta.'),
('servidores-lei-8112-posse-exercicio-vacancia-remocao',9,'Correto. O art. 14 da Lei 8.112/1990 condiciona a posse à prévia inspeção médica oficial, que verifica aptidão física e mental.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;